using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace GearLab {public static class OverloadTests {
 public static int Run(string folder){Directory.CreateDirectory(folder);var checks=new List<string>();var failures=new List<string>();Action<bool,string> c=(ok,msg)=>{if(ok)checks.Add(msg);else failures.Add(msg);};try{
  var beam=TrainStrength.Beam(10,0,100,150,100,0,10,0,200000,300,"Unknown");c(Math.Abs(beam.Reaction1+50)<1e-10&&Math.Abs(beam.Reaction2-150)<1e-10,"beam reactions -50 / 150 N");c(Math.Abs(beam.BendingMoment-5000)<1e-10,"beam moment 5000 Nmm");c(Math.Abs(beam.BendingStress-50.9295817894)<1e-8,"bending stress reference 50.9295817894 MPa");c(Math.Abs(beam.TorsionStress-50.9295817894)<1e-8,"torsion reference");c(Math.Abs(beam.Deflection.Value-.12732395447)<1e-9,"deflection hand calculation .12732395447 mm");c(Math.Abs(beam.EquivalentStress-Math.Sqrt(5)*50.9295817894)<1e-8,"Tresca combined stress");var unknown=TrainStrength.Beam(10,0,100,150,100,10,10,90,null,null,"Unknown");c(unknown.Deflection==null&&unknown.Axial1==null&&unknown.YieldMargin==null,"missing E/yield/axial scheme remain unknown");c(Math.Abs(unknown.Reaction2Y-150)<1e-8,"force angle vectors");
  var t=CompoundReducer.Example();MaterialLibrary.ApplyDefaults(t);t.OutputLoad=new TrainOutputLoad{RadialForce=25,ForceOffset=30};t.Overload=new TrainOverloadSettings{Enabled=true};var s=TrainSolver.Solve(t);c(s.Valid,"material example "+string.Join(";",s.Errors));if(s.Valid){double mass=s.Scene.Model.Parts.Where(p=>!p.Reference).Sum(p=>p.Volume()*1e-9*MaterialLibrary.For(t,p).Density);c(Math.Abs(mass-s.Mass)<1e-12,"mass manual volume*density");c(s.Strength.LimitTorque.HasValue,"known partial weak limit");c(s.Strength.Modes.Any(m=>m.Applicable&&!m.LimitTorque.HasValue),"unknown modes visible");c(s.Strength.LimitTorque==s.Strength.Modes.Where(m=>m.LimitTorque.HasValue).Min(m=>m.LimitTorque),"minimum of evaluated limits");c(!s.Strength.ReadyForManufacture,"not manufacturing approved");File.WriteAllText(Path.Combine(folder,"overload.csv"),TrainStrength.Report(s.Strength,true));File.WriteAllText(Path.Combine(folder,"overload.txt"),TrainStrength.Report(s.Strength,false));File.WriteAllText(Path.Combine(folder,"overload.json"),CADDocument.Serializer().Serialize(s.Strength));File.WriteAllText(Path.Combine(folder,"materials.assembly.json"),CADDocument.Serializer().Serialize(TransmissionExport.Spec(s.Scene.Model)));CompoundExport.PrintZip(t,s,Path.Combine(folder,"materials-print.zip"));}
  var custom=new TrainMaterial{Name="Measured steel",Kind="Metal",Density=7800,Yield=300,Shear=150,Elastic=200000,LayerFactor=1,Source="Test fixture: explicitly supplied input, not a catalogue claim"};t.Materials.Custom.Add(custom);t.Materials.Roles["shaft"]=custom.Name;t.Materials.Roles["fastener"]=custom.Name;s=TrainSolver.Solve(t);c(s.Valid&&s.Strength.Shaft.YieldMargin.HasValue,"custom shaft material");t.Save(Path.Combine(folder,"materials.train.json"));var copy=TransmissionTrain.Read(Path.Combine(folder,"materials.train.json"));c(copy.Materials.Custom.Any(m=>m.Name==custom.Name),"custom material persisted");MaterialLibrary.SaveUser(new List<TrainMaterial>{custom});c(MaterialLibrary.LoadUser().Single().Yield==300,"user library settings roundtrip");
  t.Overload.ClutchEnabled=true;t.Overload.Friction=.2;t.Overload.TargetTorque=1.2;t.Overload.MeanRadius=15;t.Overload.Surfaces=2;s=TrainSolver.Solve(t);c(s.Valid,"clutch geometry "+string.Join(";",s.Errors));if(s.Valid){c(s.Strength.LimitTorque==s.Strength.Modes.Where(m=>m.LimitTorque.HasValue).Min(m=>m.LimitTorque),"clutch included in minimum");c(Math.Abs(s.Strength.ClutchTorque.Value-1.2)<1e-10&&Math.Abs(s.Strength.SpringForce.Value-200)<1e-8,"clutch 1.2 Nm, 200 N");c(s.Scene.Model.Parts.Any(p=>p.Id=="SH_CLUTCH_MODULE")&&s.Compound.Support2>s.Compound.Support1,"clutch module and actual output supports");CompoundExport.PrintZip(t,s,Path.Combine(folder,"clutch-print.zip"));File.WriteAllText(Path.Combine(folder,"clutch.assembly.json"),CADDocument.Serializer().Serialize(TransmissionExport.Spec(s.Scene.Model)));t.Overload.TargetTorque=100;s=TrainSolver.Solve(t);c(s.Valid&&s.Strength.Notes.Any(n=>n.Contains("выше")),"unsafe clutch setting warning");}
  var visual=new OverloadVisualState{Enabled=true,Failed=true};visual.Advance(1);c(visual.OutputPhase==0,"failed output stopped");visual.Smooth=true;visual.Scale=1;visual.Advance(1);c(visual.Scale>0&&visual.Scale<1,"schematic clutch smooth lag");var robot=new RobotDocument();var j=robot.Add(null);j.MotorTorque=10;var rt=CompoundReducer.Example();MaterialLibrary.ApplyDefaults(rt);RobotTrainIntegration.Apply(j,rt,rt.Stages.Last().Id);var build=RobotCad.Build(robot);var analysis=RobotSolver.Solve(build);c(analysis.Valid&&analysis.Joints[0].ReducerLimit.HasValue,"robot reducer limit");c(analysis.Joints[0].StrengthMessage!=null&&analysis.Joints[0].StrengthMessage.Contains("разрушить"),"motor stronger than reducer warning");
  t=CompoundReducer.Example();t.OutputLoad=new TrainOutputLoad{RadialForce=double.NaN};c(!TrainSolver.Solve(t).Valid,"NaN load rejected");t=CompoundReducer.Example();MaterialLibrary.ApplyDefaults(t);t.Materials.Custom.Add(new TrainMaterial{Name="bad",Kind="FDM",Density=double.NaN,Source="user"});c(!TrainSolver.Solve(t).Valid,"NaN density rejected");t=TransmissionTrain.Example();var old=TrainSolver.Solve(t);var legacy=TrainSolver.Solve(CADDocument.Serializer().Deserialize<TransmissionTrain>(CADDocument.Serializer().Serialize(t)));c(old.Valid&&legacy.Valid&&Math.Abs(old.Mass-legacy.Mass)<1e-10,"legacy densities preserved");
 }catch(Exception ex){failures.Add(ex.ToString());}File.WriteAllText(Path.Combine(folder,"overload-results.json"),CADDocument.Serializer().Serialize(new{Passed=failures.Count==0,Checks=checks.Count,Failures=failures}));return failures.Count==0?0:1;}
}}
